"use strict";
const crypto = require('crypto');

// Session management implementation
class SessionManager {
  constructor() {
    this.sessions = new Map();
    this.userIndex = new Map(); // raw username -> sessionId
    this.rateLimiter = new Map();
    this.MAX_SESSIONS = 10000;
    this.SESSION_TTL = 3600000;
    this.RATE_LIMIT_WINDOW = 60000;
    this.RATE_LIMIT_MAX = 100;
  }

  // Validate username format strictly - no normalization to avoid collisions
  _validateUsername(username) {
    if (typeof username !== 'string' || username.length === 0 || username.length > 128) {
      throw new Error('Invalid username');
    }
    // Only allow ASCII alphanumeric, underscore, hyphen, dot
    // This prevents any Unicode normalization collision attacks
    if (!/^[a-zA-Z0-9_\-.]+$/.test(username)) {
      throw new Error('Username contains invalid characters');
    }
    return username.toLowerCase();
  }

  // Secure session token generation
  _generateToken() {
    return crypto.randomBytes(32).toString('hex');
  }

  // Rate limiting check
  _checkRateLimit(ip) {
    const now = Date.now();
    const windowStart = now - this.RATE_LIMIT_WINDOW;
    if (!this.rateLimiter.has(ip)) {
      this.rateLimiter.set(ip, []);
    }
    const attempts = this.rateLimiter.get(ip).filter(t => t > windowStart);
    this.rateLimiter.set(ip, attempts);
    if (attempts.length >= this.RATE_LIMIT_MAX) {
      return false;
    }
    attempts.push(now);
    return true;
  }

  // Validate password using constant-time comparison
  _verifyPassword(stored, provided) {
    if (typeof stored !== 'string' || typeof provided !== 'string') {
      return false;
    }
    const storedBuf = Buffer.from(stored, 'utf8');
    const providedBuf = Buffer.from(provided, 'utf8');
    if (storedBuf.length !== providedBuf.length) {
      return false;
    }
    return crypto.timingSafeEqual(storedBuf, providedBuf);
  }

  // Create authenticated session
  createSession(username, passwordHash, ip, metadata = {}) {
    if (!this._checkRateLimit(ip)) {
      return { error: 'rate_limited', retryAfter: this.RATE_LIMIT_WINDOW };
    }

    if (this.sessions.size >= this.MAX_SESSIONS) {
      this._evictExpiredSessions();
    }

    const validatedUser = this._validateUsername(username);
    const sessionToken = this._generateToken();
    const sessionId = crypto.randomUUID();

    const session = {
      id: sessionId,
      token: sessionToken,
      username: validatedUser,
      passwordHash: passwordHash,
      createdAt: Date.now(),
      expiresAt: Date.now() + this.SESSION_TTL,
      ip: ip,
      metadata: Object.freeze({ ...metadata }),
      permissions: this._resolvePermissions(validatedUser),
      active: true
    };

    // Check if user already has an active session - invalidate old one
    if (this.userIndex.has(validatedUser)) {
      const oldSessionId = this.userIndex.get(validatedUser);
      const oldSession = this.sessions.get(oldSessionId);
      if (oldSession) {
        oldSession.active = false;
        this.sessions.delete(oldSessionId);
      }
    }

    this.sessions.set(sessionId, session);
    this.userIndex.set(validatedUser, sessionId);

    return {
      sessionId: sessionId,
      token: sessionToken,
      expiresAt: session.expiresAt
    };
  }

  // Resolve user permissions based on username
  _resolvePermissions(validatedUser) {
    const adminUsers = ['admin', 'root', 'administrator'];
    if (adminUsers.includes(validatedUser)) {
      return Object.freeze({ role: 'admin', canManageUsers: true, canAccessLogs: true, canModifyConfig: true });
    }
    return Object.freeze({ role: 'user', canManageUsers: false, canAccessLogs: false, canModifyConfig: false });
  }

  // Get session by username (for admin operations)
  getSessionByUsername(username) {
    const validatedUser = this._validateUsername(username);
    const sessionId = this.userIndex.get(validatedUser);
    if (!sessionId) return null;
    const session = this.sessions.get(sessionId);
    if (!session || !session.active || Date.now() > session.expiresAt) {
      return null;
    }
    return {
      id: session.id,
      username: session.username,
      permissions: session.permissions,
      createdAt: session.createdAt
    };
  }

  // Validate session token
  validateSession(sessionId, token) {
    if (typeof sessionId !== 'string' || typeof token !== 'string') {
      return { valid: false, reason: 'invalid_input' };
    }
    const session = this.sessions.get(sessionId);
    if (!session || !session.active) {
      return { valid: false, reason: 'not_found' };
    }
    if (Date.now() > session.expiresAt) {
      session.active = false;
      return { valid: false, reason: 'expired' };
    }
    // Validate token format before comparison
    if (!/^[0-9a-f]{64}$/.test(token)) {
      return { valid: false, reason: 'invalid_token' };
    }
    const tokenBuf = Buffer.from(token, 'hex');
    const sessionBuf = Buffer.from(session.token, 'hex');
    if (!crypto.timingSafeEqual(tokenBuf, sessionBuf)) {
      return { valid: false, reason: 'invalid_token' };
    }
    return { valid: true, session: { id: session.id, username: session.username, permissions: session.permissions } };
  }

  // Elevate session permissions (requires admin approval)
  elevateSession(adminSessionId, adminToken, targetUsername) {
    const adminValidation = this.validateSession(adminSessionId, adminToken);
    if (!adminValidation.valid) {
      return { error: 'invalid_admin_session' };
    }
    if (adminValidation.session.permissions.role !== 'admin') {
      return { error: 'insufficient_permissions' };
    }

    const targetValidated = this._validateUsername(targetUsername);
    const targetSessionId = this.userIndex.get(targetValidated);
    if (!targetSessionId) {
      return { error: 'target_not_found' };
    }
    const targetSession = this.sessions.get(targetSessionId);
    if (!targetSession || !targetSession.active) {
      return { error: 'target_session_inactive' };
    }
    if (Date.now() > targetSession.expiresAt) {
      return { error: 'target_session_expired' };
    }

    // Create new permission object rather than mutating frozen one
    targetSession.permissions = Object.freeze({ role: 'admin', canManageUsers: true, canAccessLogs: true, canModifyConfig: true });
    return { success: true, elevated: targetValidated };
  }

  // Cleanup expired sessions
  _evictExpiredSessions() {
    const now = Date.now();
    for (const [id, session] of this.sessions) {
      if (now > session.expiresAt) {
        this.sessions.delete(id);
        this.userIndex.delete(session.username);
      }
    }
  }

  // Destroy session
  destroySession(sessionId, token) {
    const validation = this.validateSession(sessionId, token);
    if (!validation.valid) return { error: 'invalid_session' };
    const session = this.sessions.get(sessionId);
    if (session) {
      session.active = false;
      this.sessions.delete(sessionId);
      this.userIndex.delete(session.username);
    }
    return { success: true };
  }
}

module.exports = SessionManager;
